  ["Sogo"] = "そごう",
  ["Sogo's directory is a map from shop name to floor. Missing keys return the zero value, so you must ask comma-ok before you trust the number."] = "そごうの案内板は店名から階への map。無いキーはゼロ値を返すので、数を信じる前に comma-ok で確かめましょう。",
  ["Sort the names in place. Fill: slices.___(names)"] = "names をその場でソート。埋めてください: slices.___(names)",
  ["Sorted prices. Find 25 in log n. Then sort the unsorted ones in n log n."] = "ソート済みの価格。log n で 25 を見つけて。次に未ソートを n log n で並べ替え。",
